cmd:
. "$FIXTURES/forge/setup.sh"; fx_init
fx_remote https://gitlab.example.test/grp/proj.git
export FORGE_TOKEN=glpat-FAKE-not-a-real-token-0001
mkdir -p factory/specs
mkspec() { printf -- "---\nid: %s\ntitle: t%s\nstatus: pr-open\nbranch: %s\npr: %s\n---\n" "$1" "$1" "$2" "$3" > "factory/specs/$1-s.md"; }
st() { sed -n "s/^status: //p" "factory/specs/$1-s.md" | head -1; }
mrpath() { echo "/api/v4/projects/grp%2Fproj/merge_requests/$1"; }
mrurl() { echo "https://gitlab.example.test/grp/proj/-/merge_requests/$1"; }
openbranch() { git checkout -q -b "$1"; git commit -q --allow-empty -m "w-$1"; git checkout -q main; }
mergedbranch() { openbranch "$1"; git merge -q --no-ff --no-edit "$1"; }
recon() { "$PLUGIN_ROOT/scripts/lib/tracker.sh" reconcile-done tester >/dev/null 2>&1; }
for n in 1 2 3 4; do openbranch claude/idea-$n; mkspec 00$n claude/idea-$n "$(mrurl $n)"; done
fx_http "GET $(mrpath 1)" 200 '{"state":"opened"}'
fx_http "GET $(mrpath 2)" 500 '{"state":"merged"}'
fx_http "GET $(mrpath 3)" 200 '{"state":"closed"}'
fx_http "GET $(mrpath 4)" 200 '{"state":"merged"}'
recon
for n in 1 2 3 4; do echo "s$n=$(st 00$n)"; done
echo "reqs=$(fx_nreq)"
[[ -x "$F" ]] || FX_MISSING=127; fx_done
